117	// runTrailShow shows one trail, defaulting to the current branch's trail.
118	func runTrailShow(ctx context.Context, w, errW io.Writer, insecureHTTP bool, selector string) error {
119		return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, func(ctx context.Context, client *api.Client) error {
120			forge, owner, repo, err := resolveTrailRemote(ctx)
121			if err != nil {
122				return err
123			}
124	
125			selector = strings.TrimSpace(selector)
126			var found *api.TrailResource
127			if selector == "" {
128				branch, err := GetCurrentBranch(ctx)
129				if err != nil {
130					return fmt.Errorf("no trail selector given and current branch is unknown: %w\nhint: run 'entire trail list --status any' or pass a trail number, id, or branch", err)
131				}
132				found, err = findTrailByBranch(ctx, client, forge, owner, repo, branch)
133				if err != nil {
134					return err
135				}
136				if found == nil {
137					return fmt.Errorf("no trail found for current branch %q\nhint: run 'entire trail create' or 'entire trail list --status any'", branch)
138				}
139			} else {
140				found, err = findTrailBySelector(ctx, client, forge, owner, repo, selector)
141				if err != nil {
142					return err
143				}
144				if found == nil {
145					return fmt.Errorf("no trail %q found in %s/%s/%s (run 'entire trail list --status any')", selector, forge, owner, repo)
146				}
147			}
148	
149			printTrailDetails(w, found.ToMetadata())
150			return nil
151		})
152	}
