154	func printTrailDetails(w io.Writer, m *trail.Metadata) {
155		fmt.Fprintf(w, "Trail: %s\n", m.Title)
156		if m.Number > 0 {
157			fmt.Fprintf(w, "  Number:  %d\n", m.Number)
158		}
159		if !m.TrailID.IsEmpty() {
160			fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
161		}
162		fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
163		fmt.Fprintf(w, "  Base:    %s\n", m.Base)
164		fmt.Fprintf(w, "  Status:  %s\n", m.Status)
165		fmt.Fprintf(w, "  Author:  %s\n", m.AuthorLogin())
166		if strings.TrimSpace(m.Phase) != "" {
167			fmt.Fprintf(w, "  Phase:   %s\n", trailPhaseDisplay(m.Phase))
168		}
169		if m.Body != "" {
170			fmt.Fprintf(w, "  Body:    %s\n", m.Body)
171		}
172		if len(m.Labels) > 0 {
173			fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
174		}
175		if len(m.Assignees) > 0 {
176			fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
177		}
178		fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
179		fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
