204	func runTrailListAll(ctx context.Context, w, errW io.Writer, opts trailListOptions) error {
205		statusFilters, err := validateTrailListOptions(opts)
206		if err != nil {
207			return err
208		}
209		return runAuthenticatedDataAPI(ctx, errW, opts.InsecureHTTP, func(ctx context.Context, client *api.Client) error {
210			return runTrailListAllWithClient(ctx, w, client, opts, statusFilters)
211		})
212	}
