214	func validateTrailListOptions(opts trailListOptions) ([]trail.Status, error) {
215		if opts.Limit <= 0 {
216			return nil, errors.New("limit must be greater than 0")
217		}
218		return parseTrailStatusFilter(opts.Status)
219	}
