450	func printTrailRows(w io.Writer, trails []*trail.Metadata, showAuthor, showStatus bool) {
451		// tabwriter aligns by display columns instead of bytes, so multi-byte
452		// branch names or logins don't throw off the table.
453		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
454		showPhase := trailListHasPhase(trails)
455		columns := []string{"NUM", "BRANCH", "TITLE"}
456		if showStatus {
457			columns = append(columns, "STATUS")
458		}
459		if showPhase {
460			columns = append(columns, "PHASE")
461		}
462		if showAuthor {
463			columns = append(columns, "AUTHOR")
464		}
465		columns = append(columns, "UPDATED")
466		fmt.Fprintln(tw, "  "+strings.Join(columns, "\t"))
467		for _, t := range trails {
468			number := "-"
469			if t.Number > 0 {
470				number = strconv.Itoa(t.Number)
471			}
472			title := truncateOneLine(t.Title, 60)
473			if title == "" {
474				title = "(untitled)"
475			}
476			fields := []string{number, t.Branch, title}
477			if showStatus {
478				fields = append(fields, trailStatusDisplay(t.Status))
479			}
480			if showPhase {
481				fields = append(fields, trailPhaseDisplay(t.Phase))
482			}
483			if showAuthor {
484				fields = append(fields, t.AuthorLogin())
485			}
486			fields = append(fields, timeAgo(t.UpdatedAt))
487			fmt.Fprintln(tw, "  "+strings.Join(fields, "\t"))
488		}
489		_ = tw.Flush()
490	}
