492	func trailListHasPhase(trails []*trail.Metadata) bool {
493		for _, t := range trails {
494			if t != nil && strings.TrimSpace(t.Phase) != "" {
495				return true
496			}
497		}
498		return false
499	}
500	
501	func trailPhaseDisplay(phase string) string {
502		phase = strings.TrimSpace(phase)
503		if phase == "" {
504			return "-"
505		}
506		return strings.ReplaceAll(phase, "_", " ")
507	}
508	
509	func trailStatusListDisplay(statuses []trail.Status) string {
510		parts := make([]string, len(statuses))
511		for i, status := range statuses {
512			parts[i] = trailStatusDisplay(status)
513		}
514		return strings.Join(parts, ", ")
515	}
516	
517	func trailStatusListTitle(statuses []trail.Status) string {
518		display := trailStatusListDisplay(statuses)
519		if display == "" {
520			return ""
521		}
522		return strings.ToUpper(display[:1]) + display[1:]
523	}
524	
525	func trailStatusDisplay(status trail.Status) string {
526		return strings.ReplaceAll(string(status), "_", " ")
527	}
528	
529	// trailCountDisplay renders a count as "shown/total" when --limit truncated
530	// the list, so a capped page doesn't read as the total number of matches.
531	func trailCountDisplay(shown, total int) string {
532		if total > shown {
533			return fmt.Sprintf("%d/%d", shown, total)
534		}
535		return strconv.Itoa(shown)
536	}
537	
538	func pluralize(s string, count int) string {
539		if count == 1 {
540			return s
541		}
542		return s + "s"
543	}
