568	//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
569	func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
570		ctx := cmd.Context()
571		w := cmd.OutOrStdout()
572		errW := cmd.ErrOrStderr()
573	
574		repo, err := strategy.OpenRepository(ctx)
575		if err != nil {
576			return fmt.Errorf("failed to open repository: %w", err)
577		}
578		defer repo.Close()
579	
580		// Determine base branch.
581		if base == "" {
582			base = strategy.GetDefaultBranchName(repo)
583			if base == "" {
584				base = defaultBaseBranch
585			}
586		}
587	
588		_, currentBranch, _ := isOnDefaultBranchRepo(repo) //nolint:errcheck // best-effort; reuse the open repo for the current branch name
589		interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
590	
591		if interactive {
592			// Interactive flow: title → body → branch (derived) → status.
593			if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
594				return handleFormCancellation(w, "Trail creation", err)
595			}
596		} else {
597			// Non-interactive: derive missing values from provided flags. With
598			// --branch omitted, use the checked-out branch (a feature branch); only
599			// slug a new branch from the title when the checked-out branch is the base.
600			branch = resolveCreateBranch(branch, currentBranch, base, title, cmd.Flags().Changed("title"))
601			if title == "" {
602				title = trail.HumanizeBranchName(branch)
603			}
604		}
605		title = strings.TrimSpace(title)
606		base = strings.TrimSpace(base)
607		branch = strings.TrimSpace(branch)
608		statusStr = strings.TrimSpace(statusStr)
609		if title == "" {
610			return errors.New("trail title is required")
611		}
612		if branch == "" {
613			return errors.New("branch name is required")
614		}
615		if err := ValidateBranchName(ctx, branch); err != nil {
616			return err
617		}
618		if statusStr == "" {
619			statusStr = string(trail.StatusOpen)
620		}
621		if status := trail.Status(statusStr); !status.IsValid() {
622			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
623		}
624	
625		needsCreation := branchNeedsCreation(repo, branch)
626	
627		client, err := NewAuthenticatedAPIClient(ctx, trailInsecureHTTP(cmd))
628		if err != nil {
629			return renderDataAPIAuthError(cmd.ErrOrStderr(), err)
630		}
631		forge, owner, repoName, err := resolveTrailRemote(ctx)
632		if err != nil {
633			return err
634		}
635	
636		localBranchCreated := false
637		var remoteBranchPushed bool
638	
639		// Don't delete a remote branch we didn't create during cleanup.
640		existedOnOrigin, existErr := branchExistsOnOrigin(branch)
641		if existErr != nil {
642			fmt.Fprintf(errW, "Warning: could not check whether branch %s already exists on origin: %v\n", branch, existErr)
643			existedOnOrigin = true
644		}
645	
646		if needsCreation {
647			if existedOnOrigin {
648				if err := fetchBranchFromOrigin(branch); err != nil {
649					return fmt.Errorf("failed to fetch branch %q from origin: %w", branch, err)
650				}
651				localBranchCreated = true
652				fmt.Fprintf(w, "Fetched branch %s from origin\n", branch)
653			} else {
654				if err := createBranch(repo, branch); err != nil {
655					return fmt.Errorf("failed to create branch %q: %w", branch, err)
656				}
657				localBranchCreated = true
658				fmt.Fprintf(w, "Created branch %s\n", branch)
659			}
660		} else if currentBranch != branch {
661			fmt.Fprintf(w, "Note: trail will be created for branch %q (not the current branch)\n", branch)
662		}
663	
664		// Always push the branch first: the trail binds to a remote branch, so
665		// deliver it before creating the trail rather than letting the server
666		// backfill it at the base tip.
667		{
668			if err := pushBranchToOrigin(branch); err != nil {
669				cleanupCreatedTrailBranch(repo, branch, localBranchCreated, false, errW)
670				return fmt.Errorf("failed to push branch %q to origin: %w\nhint: the trail was not created because its branch could not be delivered to the remote.\n  - if this is an auth error, link your GitHub account and retry\n  - if this is a non-fast-forward, update branch %q from origin and retry", branch, err, branch)
671			}
672			remoteBranchPushed = !existedOnOrigin
673			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
674		}
675	
676		createReq := newTrailCreateRequest(title, body, branch, base, statusStr)
677	
678		var createResp api.TrailCreateResponse
679		resp, err := client.Post(ctx, trailsBasePath(forge, owner, repoName), createReq)
680		if err != nil {
681			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
682			return fmt.Errorf("failed to create trail: %w", err)
683		}
684		defer resp.Body.Close()
685		if err := checkTrailResponse(resp); err != nil {
686			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
687			return err
688		}
689	
690		if err := api.DecodeJSON(resp, &createResp); err != nil {
691			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
692			return fmt.Errorf("failed to decode create response: %w", err)
693		}
694	
695		fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", createResp.Trail.Title, createResp.Trail.Branch, createResp.Trail.ID)
696	
697		if needsCreation && currentBranch != branch {
698			shouldCheckout := checkout
699			if !shouldCheckout && !cmd.Flags().Changed("checkout") {
700				// Interactive: ask whether to checkout
701				form := NewAccessibleForm(
702					huh.NewGroup(
703						huh.NewConfirm().
704							Title(fmt.Sprintf("Check out branch %s?", branch)).
705							Value(&shouldCheckout),
706					),
707				)
708				if formErr := form.Run(); formErr == nil && shouldCheckout {
709					checkout = true
710				}
711			}
712			if checkout {
713				if err := CheckoutBranch(ctx, branch); err != nil {
714					return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
715				}
716				fmt.Fprintf(w, "Switched to branch %s\n", branch)
717			}
718		}
719	
720		return nil
721	}
