779	func runTrailUpdate(ctx context.Context, w, errW io.Writer, insecureHTTP bool, inputs trailUpdateInputs) error {
780		return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, func(ctx context.Context, client *api.Client) error {
781			forge, owner, repoName, err := resolveTrailRemote(ctx)
782			if err != nil {
783				return err
784			}
785	
786			// Determine branch.
787			branch := inputs.Branch
788			if branch == "" {
789				branch, err = GetCurrentBranch(ctx)
790				if err != nil {
791					return fmt.Errorf("failed to determine current branch: %w", err)
792				}
793			}
794	
795			// Find the trail by branch.
796			found, err := findTrailByBranch(ctx, client, forge, owner, repoName, branch)
797			if err != nil {
798				return err
799			}
800			if found == nil {
801				return fmt.Errorf("no trail found for branch %q", branch)
802			}
803	
804			// Interactive mode when no update flags are provided.
805			statusStr := inputs.Status
806			title := inputs.Title
807			body := inputs.Body
808			noFlags := !inputs.StatusChanged && !inputs.TitleChanged && !inputs.BodyChanged && inputs.LabelAdd == nil && inputs.LabelRemove == nil
809			if noFlags {
810				metadata := found.ToMetadata()
811				// Build status options with current value as default.
812				var statusOptions []huh.Option[string]
813				for _, s := range trail.ValidStatuses() {
814					if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
815						continue
816					}
817					label := string(s)
818					if s == metadata.Status {
819						label += " (current)"
820					}
821					statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
822				}
823				statusStr = string(metadata.Status)
824				title = metadata.Title
825				body = metadata.Body
826	
827				form := NewAccessibleForm(
828					huh.NewGroup(
829						huh.NewSelect[string]().
830							Title("Status").
831							Options(statusOptions...).
832							Value(&statusStr),
833						huh.NewInput().
834							Title("Title").
835							Value(&title),
836						huh.NewText().
837							Title("Body").
838							Value(&body),
839					),
840				)
841				if formErr := form.Run(); formErr != nil {
842					return handleFormCancellation(w, "Trail update", formErr)
843				}
844				inputs.StatusChanged = true
845				inputs.TitleChanged = true
846				inputs.BodyChanged = true
847			}
848	
849			statusStr = strings.TrimSpace(statusStr)
850			title = strings.TrimSpace(title)
851			if err := validateTrailUpdateFields(trailUpdateInputs{
852				Status:        statusStr,
853				StatusChanged: inputs.StatusChanged,
854				Title:         title,
855				TitleChanged:  inputs.TitleChanged,
856			}); err != nil {
857				return err
858			}
859	
860			// Build update request with only changed fields.
861			updateReq := buildTrailUpdateRequest(found, trailUpdateInputs{
862				Status:        statusStr,
863				StatusChanged: inputs.StatusChanged,
864				Title:         title,
865				TitleChanged:  inputs.TitleChanged,
866				Body:          body,
867				BodyChanged:   inputs.BodyChanged,
868				LabelAdd:      inputs.LabelAdd,
869				LabelRemove:   inputs.LabelRemove,
870			})
871	
872			// The single-trail endpoint is keyed by trail number, not id; the server
873			// rejects an id here with "Invalid trail number format".
874			if found.Number <= 0 {
875				return fmt.Errorf("trail for branch %q has no number yet; cannot update", branch)
876			}
877			resp, err := client.Patch(ctx, trailNumberPath(forge, owner, repoName, found.Number), updateReq)
878			if err != nil {
879				return fmt.Errorf("failed to update trail: %w", err)
880			}
881			defer resp.Body.Close()
882			if err := checkTrailResponse(resp); err != nil {
883				return err
884			}
885	
886			var updateResp api.TrailUpdateResponse
887			if err := api.DecodeJSON(resp, &updateResp); err != nil {
888				return fmt.Errorf("failed to decode update response: %w", err)
889			}
890	
891			fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
892			return nil
893		})
894	}
