896	func validateTrailUpdateFields(inputs trailUpdateInputs) error {
897		if inputs.TitleChanged && strings.TrimSpace(inputs.Title) == "" {
898			return errors.New("trail title is required")
899		}
900		if inputs.StatusChanged {
901			status := trail.Status(strings.TrimSpace(inputs.Status))
902			if !status.IsValid() {
903				return fmt.Errorf("invalid status %q: valid values are %s", inputs.Status, formatValidStatuses())
904			}
905		}
906		return nil
907	}
