909	// buildTrailUpdateRequest constructs a PATCH request body from the current trail and the requested changes.
910	func buildTrailUpdateRequest(current *api.TrailResource, inputs trailUpdateInputs) api.TrailUpdateRequest {
911		var req api.TrailUpdateRequest
912	
913		if inputs.StatusChanged {
914			req.Status = &inputs.Status
915		}
916		if inputs.TitleChanged {
917			req.Title = &inputs.Title
918		}
919		if inputs.BodyChanged {
920			req.Body = &inputs.Body
921		}
922	
923		// Handle label changes: merge adds, remove removes.
924		if len(inputs.LabelAdd) > 0 || len(inputs.LabelRemove) > 0 {
925			labels := make([]string, 0, len(current.Labels)+len(inputs.LabelAdd))
926			labels = append(labels, current.Labels...)
927			for _, l := range inputs.LabelAdd {
928				found := false
929				for _, existing := range labels {
930					if existing == l {
931						found = true
932						break
933					}
934				}
935				if !found {
936					labels = append(labels, l)
937				}
938			}
939			for _, l := range inputs.LabelRemove {
940				for i, existing := range labels {
941					if existing == l {
942						labels = append(labels[:i], labels[i+1:]...)
943						break
944					}
945				}
946			}
947			req.Labels = &labels
948		}
949	
950		return req
951	}
