953	// parseTrailNumberArg parses an optional positional trail-number argument.
954	// It returns 0 when no argument is supplied; a supplied value must be a
955	// positive integer (the server keys single-trail endpoints by number).
956	func parseTrailNumberArg(args []string) (int, error) {
957		if len(args) == 0 {
958			return 0, nil
959		}
960		n, err := strconv.Atoi(args[0])
961		if err != nil || n <= 0 {
962			return 0, fmt.Errorf("invalid trail number %q: expected a positive integer (see 'entire trail list')", args[0])
963		}
964		return n, nil
965	}
