997	func runTrailDelete(cmd *cobra.Command, number int, branch string, force bool) error {
998		ctx := cmd.Context()
999		w := cmd.OutOrStdout()
1000	
1001		return runAuthenticatedDataAPI(ctx, cmd.ErrOrStderr(), trailInsecureHTTP(cmd), func(ctx context.Context, client *api.Client) error {
1002			forge, owner, repo, err := resolveTrailRemote(ctx)
1003			if err != nil {
1004				return err
1005			}
1006	
1007			// Resolve the target trail. An explicit number is authoritative (a
1008			// lookup is best-effort, only to label the confirmation); otherwise the
1009			// branch's trail supplies the number.
1010			title := ""
1011			if number == 0 {
1012				if branch == "" {
1013					branch, err = GetCurrentBranch(ctx)
1014					if err != nil {
1015						return fmt.Errorf("failed to determine current branch: %w", err)
1016					}
1017				}
1018				found, ferr := findTrailByBranch(ctx, client, forge, owner, repo, branch)
1019				if ferr != nil {
1020					return ferr
1021				}
1022				if found == nil {
1023					return fmt.Errorf("no trail found for branch %q", branch)
1024				}
1025				if found.Number <= 0 {
1026					return fmt.Errorf("trail for branch %q has no number yet; cannot delete", branch)
1027				}
1028				number = found.Number
1029				title = found.Title
1030			} else if found, ferr := findTrailByNumber(ctx, client, forge, owner, repo, number); ferr == nil && found != nil {
1031				title = found.Title
1032			}
1033	
1034			proceed, err := confirmTrailDeletion(ctx, w, number, title, force, interactive.CanPromptInteractively())
1035			if err != nil {
1036				return err
1037			}
1038			if !proceed {
1039				return nil
1040			}
1041	
1042			if err := deleteTrailByNumber(ctx, client, forge, owner, repo, number); err != nil {
1043				return err
1044			}
1045	
1046			fmt.Fprintf(w, "Deleted trail #%d\n", number)
1047			return nil
1048		})
1049	}
