1051	// deleteTrailByNumber deletes the trail with the given integer number and
1052	// verifies the server's {ok:true} signal. CheckResponse accepts any 2xx and the
1053	// body is otherwise unread, so a destructive delete must confirm ok before
1054	// reporting success (decoding also drains the body for connection reuse).
1055	func deleteTrailByNumber(ctx context.Context, client *api.Client, forge, owner, repo string, number int) error {
1056		resp, err := client.Delete(ctx, trailNumberPath(forge, owner, repo, number))
1057		if err != nil {
1058			return fmt.Errorf("failed to delete trail: %w", err)
1059		}
1060		defer resp.Body.Close()
1061		if err := checkTrailResponse(resp); err != nil {
1062			return err
1063		}
1064		var delResp api.TrailDeleteResponse
1065		if err := api.DecodeJSON(resp, &delResp); err != nil {
1066			return fmt.Errorf("failed to decode delete response: %w", err)
1067		}
1068		if !delResp.OK {
1069			return fmt.Errorf("trail API did not confirm deletion of trail #%d", number)
1070		}
1071		return nil
1072	}
1073	
1074	// confirmTrailDeletion decides whether a trail delete should proceed. With
1075	// force it proceeds silently. Otherwise it requires an interactive terminal:
1076	// when none is available it refuses (returns an error) rather than deleting
1077	// unprompted; when one is, it shows a confirmation form. canPrompt is passed in
1078	// (rather than queried) so the decision is unit-testable without a TTY.
1079	func confirmTrailDeletion(ctx context.Context, w io.Writer, number int, title string, force, canPrompt bool) (bool, error) {
1080		if force {
1081			return true, nil
1082		}
1083		if !canPrompt {
1084			return false, fmt.Errorf("refusing to delete trail #%d without confirmation; pass --force", number)
1085		}
1086		// huh opens the TTY during form startup regardless of context state, so
1087		// guard explicitly to honor an already-cancelled command context.
1088		if ctx.Err() != nil {
1089			return false, nil //nolint:nilerr // cancelled context is a clean skip, not an error
1090		}
1091		prompt := fmt.Sprintf("Delete trail #%d?", number)
1092		if title != "" {
1093			prompt = fmt.Sprintf("Delete trail #%d (%s)?", number, title)
1094		}
1095		confirmed := false
1096		form := NewAccessibleForm(
1097			huh.NewGroup(huh.NewConfirm().Title(prompt).Value(&confirmed)),
1098		)
1099		if err := form.RunWithContext(ctx); err != nil {
1100			// A user abort (Esc) or context cancel (Ctrl+C) is a clean cancel, not
1101			// an error — mirror confirmDoctorFix / uiform.PromptYN.
1102			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
1103				return false, nil
1104			}
1105			return false, fmt.Errorf("trail deletion prompt: %w", err)
1106		}
1107		if !confirmed {
1108			fmt.Fprintln(w, "Trail deletion cancelled.")
1109			return false, nil
1110		}
1111		return true, nil
1112	}
