1192	
1193	// findTrailByBranch looks up a trail by branch name via the list API.
1194	func findTrailBySelector(ctx context.Context, client *api.Client, forge, owner, repo, selector string) (*api.TrailResource, error) {
1195		selector = strings.TrimSpace(selector)
1196		if selector == "" {
1197			return nil, nil //nolint:nilnil // empty selector means not found for this helper
1198		}
1199		if n, ok := parseTrailNumberSelector(selector); ok {
1200			found, err := findTrailByNumber(ctx, client, forge, owner, repo, n)
1201			if err != nil || found != nil {
1202				return found, err
1203			}
1204		}
1205		return findTrail(ctx, client, forge, owner, repo, func(t api.TrailResource) bool {
1206			return t.ID == selector || t.Branch == selector
1207		})
1208	}
1209	
1210	func parseTrailNumberSelector(selector string) (int, bool) {
1211		n, err := strconv.Atoi(strings.TrimSpace(selector))
1212		if err != nil || n <= 0 {
1213			return 0, false
1214		}
1215		return n, true
1216	}
1217	
1218	func findTrailByBranch(ctx context.Context, client *api.Client, forge, owner, repo, branch string) (*api.TrailResource, error) {
1219		return findTrail(ctx, client, forge, owner, repo, func(t api.TrailResource) bool {
1220			return t.Branch == branch
1221		})
1222	}
1223	
1224	// findTrailByNumber looks up a trail by numeric identifier via the list API.
1225	func findTrailByNumber(ctx context.Context, client *api.Client, forge, owner, repo string, number int) (*api.TrailResource, error) {
1226		return findTrail(ctx, client, forge, owner, repo, func(t api.TrailResource) bool {
1227			return t.Number == number
1228		})
1229	}
1230	
1231	func findTrail(ctx context.Context, client *api.Client, forge, owner, repo string, match func(api.TrailResource) bool) (*api.TrailResource, error) {
1232		// The list endpoint paginates; walk bounded pages so branch/number/id lookups do
1233		// not silently miss older trails beyond the first server-max page.
1234		offset := 0
1235		previousPageSignature := ""
1236		for range trailFindMaxPages {
1237			resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo)+trailListQueryWithOffset(nil, "", trailListServerMaxLimit, offset))
1238			if err != nil {
1239				return nil, fmt.Errorf("list trails: %w", err)
1240			}
1241	
1242			var listResp api.TrailListResponse
1243			decodeErr := func() error {
1244				defer resp.Body.Close()
1245				if err := checkTrailResponse(resp); err != nil {
1246					return err
1247				}
1248				if err := api.DecodeJSON(resp, &listResp); err != nil {
1249					return fmt.Errorf("decode trail list: %w", err)
1250				}
1251				return nil
1252			}()
1253			if decodeErr != nil {
1254				return nil, decodeErr
1255			}
1256	
1257			for i := range listResp.Trails {
1258				if match(listResp.Trails[i]) {
1259					return &listResp.Trails[i], nil
1260				}
1261			}
1262	
1263			pageLen := len(listResp.Trails)
1264			if pageLen == 0 || pageLen < trailListServerMaxLimit {
1265				break
1266			}
1267			if listResp.Total == 0 {
1268				pageSignature := trailListPageSignature(listResp.Trails)
1269				if pageSignature != "" && pageSignature == previousPageSignature {
1270					break
1271				}
1272				previousPageSignature = pageSignature
1273			}
1274			offset += pageLen
1275			if listResp.Total > 0 && offset >= listResp.Total {
1276				break
1277			}
1278		}
1279		return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
1280	}
1281	
1282	func trailListPageSignature(trails []api.TrailResource) string {
1283		if len(trails) == 0 {
1284			return ""
1285		}
1286		first := trails[0]
1287		last := trails[len(trails)-1]
1288		return fmt.Sprintf("%s/%d/%s:%s/%d/%s", first.ID, first.Number, first.Branch, last.ID, last.Number, last.Branch)
1289	}
1290	
1291	// trailsBasePath returns the API path prefix for trails endpoints
1292	// (e.g., "/api/v1/trails/gh/org/repo").
1293	func trailsBasePath(forge, owner, repo string) string {
1294		return fmt.Sprintf("/api/v1/trails/%s/%s/%s", forge, owner, repo)
1295	}
1296	
1297	// trailNumberPath returns the single-trail API path keyed by integer trail
1298	// number (e.g. "/api/v1/trails/gh/acme/repo/575"). The server validates an
1299	// integer here and rejects the trail UUID, so callers must pass Number, not ID.
1300	func trailNumberPath(forge, owner, repo string, number int) string {
1301		return trailsBasePath(forge, owner, repo) + "/" + strconv.Itoa(number)
1302	}
1303	
1304	// resolveTrailRemote resolves the origin remote and ensures the forge is
1305	// known to the trails API. Without this guard, an unmapped host (e.g.
1306	// gitlab.com, or a misconfigured entire:// URL with no forge prefix)
1307	// produces a malformed `/api/v1/trails//owner/repo` path that the server
1308	// rejects with an opaque error instead of a clear "unsupported forge" one.
1309	func resolveTrailRemote(ctx context.Context) (forge, owner, repo string, err error) {
1310		forge, owner, repo, err = gitremote.ResolveRemoteRepo(ctx, "origin")
1311		if err != nil {
1312			return "", "", "", fmt.Errorf("failed to resolve repository: %w", err)
1313		}
1314		if forge == "" {
1315			return "", "", "", errors.New("origin remote is not on a forge supported by Entire trails (supported: github.com)")
1316		}
1317		return forge, owner, repo, nil
1318	}
1319	
1320	// checkTrailResponse checks the API response and returns user-friendly errors.
1321	// For auth failures, it appends a hint to re-authenticate while preserving the server's error message.
1322	func checkTrailResponse(resp *http.Response) error {
1323		if err := api.CheckResponse(resp); err != nil {
1324			if resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden {
1325				return fmt.Errorf("%w — run 'entire login' to re-authenticate", err)
1326			}
1327			return fmt.Errorf("trail API: %w", err)
1328		}
1329		return nil
1330	}
1331	
1332	// resolveCreateBranch picks the branch a non-interactive `trail create` targets.
1333	// An explicit --branch always wins. Otherwise, on a feature branch it uses the
1334	// checked-out branch; when the checked-out branch IS the base (the trail's
1335	// target/default branch) — or HEAD is detached — it derives a new branch from
1336	// the title when one was given (starting fresh work), else falls back to current.
1337	// Comparing against the already-resolved base keeps this consistent with how
1338	// `base` itself was detected (avoids a second, divergent default-branch lookup).
1339	func resolveCreateBranch(branchFlag, currentBranch, base, title string, titleProvided bool) string {
1340		if branchFlag != "" {
1341			return branchFlag
1342		}
1343		if titleProvided && (currentBranch == base || currentBranch == "") {
1344			return slugifyTitle(title)
1345		}
1346		return currentBranch
1347	}
1348	
1349	// slugifyTitle converts a title string into a branch-friendly slug.
1350	// Example: "Add user authentication" -> "add-user-authentication"
1351	func slugifyTitle(title string) string {
1352		s := strings.ToLower(strings.TrimSpace(title))
1353		// Replace spaces and underscores with hyphens
1354		s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
1355		// Remove anything that's not alphanumeric, hyphen, or slash
1356		var b strings.Builder
1357		prevHyphen := false
1358		for _, r := range s {
1359			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
1360				b.WriteRune(r)
1361				prevHyphen = false
1362			} else if r == '-' && !prevHyphen {
1363				b.WriteRune('-')
1364				prevHyphen = true
1365			}
1366		}
1367		return strings.Trim(b.String(), "-")
1368	}
1369	
1370	// branchNeedsCreation checks if a branch exists locally.
1371	func branchNeedsCreation(repo *git.Repository, branchName string) bool {
1372		_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
1373		return err != nil
1374	}
1375	
1376	// createBranch creates a new local branch pointing at HEAD without checking it out.
1377	func createBranch(repo *git.Repository, branchName string) error {
1378		head, err := repo.Head()
1379		if err != nil {
1380			return fmt.Errorf("failed to get HEAD: %w", err)
1381		}
1382		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
1383		if err := repo.Storer.SetReference(ref); err != nil {
1384			return fmt.Errorf("failed to create branch ref: %w", err)
1385		}
1386		return nil
1387	}
1388	
1389	func cleanupCreatedTrailBranch(repo *git.Repository, branchName string, localCreated, remotePushed bool, errW io.Writer) {
1390		localRemoved := !localCreated
1391		if localCreated {
1392			branchRef := plumbing.NewBranchReferenceName(branchName)
1393			if head, err := repo.Head(); err == nil && head.Name() == branchRef {
1394				fmt.Fprintf(errW, "Warning: not deleting local branch %s after trail creation failed because it is checked out; switch branches and run 'git branch -D %s' if you do not need it\n", branchName, branchName)
1395			} else if err := repo.Storer.RemoveReference(branchRef); err != nil {
1396				fmt.Fprintf(errW, "Warning: failed to delete local branch %s after trail creation failed: %v; run 'git branch -D %s' if you do not need it\n", branchName, err, branchName)
1397			} else {
1398				localRemoved = true
1399			}
1400		}
1401		if remotePushed {
1402			if !localRemoved {
1403				fmt.Fprintf(errW, "Warning: not deleting remote branch %s after trail creation failed because local cleanup did not complete; run 'git push origin --delete %s' if you do not need it\n", branchName, branchName)
1404				return
1405			}
1406			if err := deleteBranchFromOrigin(branchName); err != nil {
1407				fmt.Fprintf(errW, "Warning: failed to delete remote branch %s after trail creation failed: %v\n", branchName, err)
1408			}
1409		}
1410	}
1411	
1412	func fetchBranchFromOrigin(branchName string) error {
1413		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
1414		defer cancel()
1415		if err := ValidateBranchName(ctx, branchName); err != nil {
1416			return err
1417		}
1418		refspec := fmt.Sprintf("refs/heads/%s:refs/heads/%s", branchName, branchName)
1419		cmd := exec.CommandContext(ctx, "git", "fetch", "--no-tags", "origin", refspec)
1420		if output, err := cmd.CombinedOutput(); err != nil {
1421			return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
1422		}
1423		return nil
1424	}
1425	
1426	// pushBranchToOrigin pushes a branch to the origin remote.
1427	func pushBranchToOrigin(branchName string) error {
1428		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
1429		defer cancel()
1430		cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
1431		if output, err := cmd.CombinedOutput(); err != nil {
1432			return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
1433		}
1434		return nil
1435	}
1436	
1437	// branchExistsOnOrigin reports whether origin already has a branch with the
1438	// given name, so callers can avoid treating a pre-existing remote branch as one
1439	// they created.
1440	func branchExistsOnOrigin(branchName string) (bool, error) {
1441		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
1442		defer cancel()
1443		cmd := exec.CommandContext(ctx, "git", "ls-remote", "--heads", "origin", branchName)
1444		output, err := cmd.CombinedOutput()
1445		if err != nil {
1446			return false, fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
1447		}
1448		return strings.TrimSpace(string(output)) != "", nil
1449	}
1450	
1451	func deleteBranchFromOrigin(branchName string) error {
1452		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
1453		defer cancel()
1454		cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "origin", "--delete", branchName)
1455		if output, err := cmd.CombinedOutput(); err != nil {
1456			outputText := strings.TrimSpace(string(output))
1457			if strings.Contains(outputText, "remote ref does not exist") {
1458				return nil
1459			}
1460			return fmt.Errorf("%s: %w", outputText, err)
1461		}
1462		return nil
1463	}
